/**
 * Module to handle the kebab (action) menu on a program page
 *
 * @module     tool_program/kebab_menu
 * @author     2022 Odei Alba <odei.alba@moodle.com>
 * @copyright  2022 Moodle Pty Ltd <support@moodle.com>
 * @license    Moodle Workplace License, distribution is restricted, contact support@moodle.com
 */

"use strict";

import Notification from 'core/notification';
import {get_string as getString} from 'core/str';
import Pending from "core/pending";
import {prefetchStrings} from 'core/prefetch';
import {
    archiveProgram,
    duplicateProgram,
    updateProgramVisibility
} from 'tool_program/local/repository';

/** @type {Object} The list of selectors for the program area. */
const Selectors = {
    DuplicateProgram: "[data-action='duplicate']",
    ArchiveProgram: "[data-action='archive']",
    UpdateProgramVisibility: "[data-action='updatevisibility']",
    HideProgram: "[data-action='updatevisibility'][data-visibility='0']",
    ShowProgram: "[data-action='updatevisibility'][data-visibility='1']",
    HiddenFromLearnersBadge: ".hiddenfromlearnersbadge",
};

export const init = () => {
    prefetchStrings('tool_program', [
        'archivedconfirmation',
        'archive',
        'confirmduplicate',
    ]);

    prefetchStrings('moodle', [
        'confirm',
        'ok',
    ]);

    document.addEventListener('click', (event) => {
        const archiveProgramElement = event.target.closest(Selectors.ArchiveProgram);
        if (archiveProgramElement) {
            event.preventDefault();
            archiveProgramHandler(archiveProgramElement);
        }

        const duplicateProgramElement = event.target.closest(Selectors.DuplicateProgram);
        if (duplicateProgramElement) {
            event.preventDefault();
            duplicateProgramHandler(duplicateProgramElement);
        }

        const updateProgramVisibilityElement = event.target.closest(Selectors.UpdateProgramVisibility);
        if (updateProgramVisibilityElement) {
            event.preventDefault();
            updateProgramVisibilityHandler(updateProgramVisibilityElement);
        }
    });
};

/**
 * Handles archive a Program.
 *
 * @param {Element} element
 */
const archiveProgramHandler = (element) => {
    const {programid, name} = element.dataset;

    // Return focus to the action menu toggle.
    const triggerElement = element.closest('.dropdown').querySelector('.dropdown-toggle');
    Notification.saveCancelPromise(
        getString('confirm', 'moodle'),
        getString('archivedconfirmation', 'tool_program', name),
        getString('archive', 'tool_program'),
        {triggerElement}
    ).then(() => {
        const pendingPromise = new Pending('tool/program:archiveProgram');

        return archiveProgram(programid)
            .then((data) => {
                if (data.result) {
                    window.location.href = element.href;
                }
                return pendingPromise.resolve();
            }).catch(Notification.exception);
    }).catch(() => {
        return;
    });
};

/**
 * Handles duplicate a Program.
 *
 * @param {Element} element
 */
const duplicateProgramHandler = (element) => {
    const programid = element.dataset.programid;

    // Return focus to the action menu toggle.
    const triggerElement = element.closest('.dropdown').querySelector('.dropdown-toggle');
    Notification.saveCancelPromise(
        getString('confirm', 'moodle'),
        getString('confirmduplicate', 'tool_program'),
        getString('ok', 'moodle'),
        {triggerElement}
    ).then(() => {
        const pendingPromise = new Pending('tool/program:duplicateProgram');

        return duplicateProgram(programid)
            .then((data) => {
                if (data.result) {
                    window.location.href = data.redirecturl;
                }
                return pendingPromise.resolve();
            }).catch(Notification.exception);
    }).catch(() => {
        return;
    });
};

/**
 * Updates a Program visibility.
 *
 * @param {Element} element
 */
const updateProgramVisibilityHandler = (element) => {
    const pendingPromise = new Pending('tool/program:updateProgramVisibility');
    const {programid, visibility} = element.dataset;

    updateProgramVisibility(programid, visibility)
        .then(function(data) {
            if (data.result) {
                const showProgram = document.querySelector(Selectors.ShowProgram);
                const hideProgram = document.querySelector(Selectors.HideProgram);
                const hiddenFromLearnersBadge = document.querySelector(Selectors.HiddenFromLearnersBadge);

                showProgram.classList.toggle('hidden');
                hideProgram.classList.toggle('hidden');
                hiddenFromLearnersBadge.classList.toggle('hidden');
            }

            return pendingPromise.resolve();
        }).catch(Notification.exception);
};
